#include <cstdint>
struct EventNode { std::int64_t sequence; EventNode* next; };
bool EraseKnownNode(EventNode* target) {
    if (target == nullptr || target->next == nullptr) return false;
    EventNode* successor = target->next;
    target->sequence = successor->sequence;
    target->next = successor->next;
    delete successor;
    return true;
}
